import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf;
    static int pos;

    static long nextLong() {
        while (buf[pos] <= ' ') pos++;
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] > ' ') r = r * 10 + (buf[pos++] - '0');
        return neg ? -r : r;
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        int n = (int) nextLong(), m = (int) nextLong();
        int k = n + m;
        long[][] v = new long[k][];
        for (int i = 0; i < k; i++) v[i] = new long[] {nextLong(), nextLong()};
        Arrays.sort(v, (a, b) -> a[0] != b[0] ? Long.compare(a[0], b[0]) : Long.compare(a[1], b[1]));
        List<long[]> res = new ArrayList<>();
        for (long[] p : v) {
            if (!res.isEmpty() && p[0] <= res.get(res.size() - 1)[1]) {
                long[] last = res.get(res.size() - 1);
                last[1] = Math.max(last[1], p[1]);
            } else {
                res.add(new long[] {p[0], p[1]});
            }
        }
        StringBuilder sb = new StringBuilder();
        sb.append(res.size()).append('\n');
        for (long[] p : res) sb.append(p[0]).append(' ').append(p[1]).append('\n');
        System.out.print(sb);
    }
}

package main

import (
	"bufio"
	"os"
	"sort"
	"strconv"
)

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Buffer(make([]byte, 1<<20), 1<<20)
	sc.Split(bufio.ScanWords)
	next := func() int {
		sc.Scan()
		v, _ := strconv.Atoi(sc.Text())
		return v
	}
	n, m := next(), next()
	v := make([][2]int, n+m)
	for i := range v {
		v[i][0], v[i][1] = next(), next()
	}
	sort.Slice(v, func(a, b int) bool {
		if v[a][0] != v[b][0] {
			return v[a][0] < v[b][0]
		}
		return v[a][1] < v[b][1]
	})
	var res [][2]int
	for _, p := range v {
		if len(res) > 0 && p[0] <= res[len(res)-1][1] {
			res[len(res)-1][1] = max(res[len(res)-1][1], p[1])
		} else {
			res = append(res, p)
		}
	}
	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()
	w.WriteString(strconv.Itoa(len(res)) + "\n")
	for _, p := range res {
		w.WriteString(strconv.Itoa(p[0]) + " " + strconv.Itoa(p[1]) + "\n")
	}
}
